#include "stdafx.h"#include <HcdDataTypes_.h>#include <RsuX.h>#include <rsuNoNames.h>#include <hashRSU.h>#include <UtilsHCD.h>#pragma comment( lib, "UtilsHCD.lib" )extern KNoName g_IoMemory, g_SharedMemory;using namespace nRSUx;static const DWORD s_iosID[] = { W_AI::TypeID, W_DO::TypeID, W_AO::TypeID, W_8DI::TypeID, W_8DO::TypeID };static const DWORD s_sharID[] = { W_DIGVAR::TypeID, W_ANAVAR::TypeID };SParamInfo RsuConnectParamInfo( LPCSTR pszPointName, LPSTR pszIOtype, LPCSTR pSuffix ){  SParamInfo info;  int domain = CreateHASH16( pSuffix );  CBase *pBase = NULL;  char splitName[128];  strcpy_s( splitName, pszPointName );  char *p = splitName;  LPSTR pField = strrchr( splitName, '.' );  if( pField )  {    *pField = 0;    pField++;  }    for( int i=0; i<_countof(s_iosID); ++i )  {    pBase = g_IoMemory.FindStruct( splitName, s_iosID[i], domain );    if( pBase )      break;  }  if( !pBase && pField )  {    for( int i=0; i<_countof(s_sharID); ++i )    {      pBase = g_SharedMemory.FindStruct( pszPointName, s_sharID[i], domain );      if( pBase )        break;    }  }  if( !pBase )    return info;  switch( pBase->ID_CLASS )  {  case W_DIGVAR::TypeID:    {      W_DIGVAR *W = (W_DIGVAR*)pBase;      info << &W->PV;    }    break;  case W_ANAVAR::TypeID:    {      W_ANAVAR *W = (W_ANAVAR*)pBase;      info << &W->PV;    }    break;  case W_AI::TypeID:    {      W_AI *W = (W_AI*)pBase;      info << (tAnalog32*)&W->RAW;    }    break;  case W_AO::TypeID:    {      W_AO *W = (W_AO*)pBase;      info << (tAnalog32*)&W->RAW;    }    break;  case W_8DI::TypeID:    {      SValueDef* pDef = NameToValueHCD( pBase->ID_CLASS, pField );      if( pDef )      {        BYTE *p = (BYTE*)pBase;        p += pDef->dwShift;        switch( pDef->eVal )        {        case enumValueBol:          info << (bool*)p;          break;        default:          ASSD(0);          break;        }      }    }    break;  case W_DO::TypeID:    {      W_DO *W = (W_DO*)pBase;      info << (tBool*)&W->RAW;    }    break;  case W_8DO::TypeID:    {      SValueDef* pDef = NameToValueHCD( pBase->ID_CLASS, pField );      if( pDef )      {        BYTE *p = (BYTE*)pBase;        p += pDef->dwShift;        switch( pDef->eVal )        {        case enumValueBol:          info << (bool*)p;          break;        default:          ASSD(0);          break;        }      }    }    break;  }  return info;}